using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
using NAudio.Wave;
namespace Ahenk;
public static class CollectionUiTests
{
 static T Field<T>(MainWindow owner,string name)=>(T)typeof(MainWindow).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance)!.GetValue(owner)!;
 static void Set(MainWindow owner,string name,object value)=>typeof(MainWindow).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(owner,value);
 static object? Call(MainWindow owner,string name,params object[] args)=>typeof(MainWindow).GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(owner,args);
 static async Task Wait(Func<bool> ready){for(int i=0;i<600;i++){if(ready())return;await Task.Delay(10);}throw new Exception("Collection UI timeout");}
 public static async Task Run(string directory)
 {
  Directory.CreateDirectory(directory);var checks=new List<object>();void Check(bool value,string name){checks.Add(new{name,passed=value});if(!value)throw new Exception(name);}
  Application.Current.ShutdownMode=ShutdownMode.OnExplicitShutdown;Themes.Load();MainWindow? window=null;
  const string raw="Kaynak: 16 bit / 44,1 kHz / 2 kanal → Soundbar (Realtek (R) Audio)\nWASAPI Paylaşımlı · 32 bit / Windows: 96 kHz\nReplayGain kapalı · özgün örnekler\nAkış decoder · uyumlu parçalarda kesintisiz\nSes %55 · dijital zayıflatma · özgün örnek değerleri değişir\nWavPack: Hybrid + correction · lossless\nDAC çıkışında bit-perfect ölçümü yapılmadı.";
  try
  {
   string compact=string.Join("\n",raw.Split('\n').Take(2));var preferences=new SignalDisplayPreferences();Check(preferences.ShowHeading&&preferences.Format(raw)==compact,"Default signal shows heading, source, device and output only");preferences.Hidden=[];Check(preferences.Format(raw)==raw,"Optional signal fields can all be enabled");preferences.Hidden=["source"];Check(!preferences.Format(raw).Contains("Kaynak:")&&preferences.Format(raw).Contains("Çıkış: Soundbar"),"Source format and device visibility can be controlled independently");preferences.Hidden=["device"];Check(preferences.Format(raw).Contains("Kaynak: 16 bit")&&!preferences.Format(raw).Contains("Soundbar"),"Device hiding preserves source format and output mode");
   foreach(var (key,fragment) in new[]{("output","WASAPI"),("gain","ReplayGain"),("decoder","Akış decoder"),("volume","Ses %55"),("wavpack","WavPack:"),("notes","DAC çıkışında")}){preferences.Hidden=[key];Check(!preferences.Format(raw).Contains(fragment),"Optional signal field is filtered separately: "+key);}
   preferences.Hidden=SignalDisplayPreferences.Choices.Select(choice=>choice.Key).ToList();Check(preferences.Format(raw)=="Bilgileri seçmek için sağ tıkla.","Hiding every optional field retains a discoverable right-click hint");Check(preferences.Format("Ses çıkışı durdu (0x80070057). Teknik ayrıntı kaydedildi.").StartsWith("Ses çıkışı durdu"),"Playback failures remain visible even when all technical fields are hidden");Check(preferences.Format(raw+"\nSes tamponu hazırlanıyor…").Contains("Ses tamponu hazırlanıyor"),"Buffering status remains visible independently of technical fields");preferences.Hidden=["unknown","gain","gain"];preferences.Validate();Check(preferences.Hidden.SequenceEqual(["gain"]),"Unknown and duplicate saved signal fields normalize safely");
   string source=Path.Combine(directory,"silence.wav");var format=new WaveFormat(44100,16,2);using(var writer=new WaveFileWriter(source,format))writer.Write(new byte[format.AverageBytesPerSecond],0,format.AverageBytesPerSecond);var rows=new List<Track>();for(int i=0;i<4;i++){var track=await MetadataReader.Read(source,default);track.Path=source+"#"+i;track.SourcePath=source;track.Title="Track "+i;track.Artist=track.AlbumArtist="Artist "+i;track.Album="Album "+i;rows.Add(track);}using(var store=new LibraryStore())store.SaveMany(rows);
   Environment.SetEnvironmentVariable("LYRA_ARTIST_PHOTOS_OFFLINE","1");window=new MainWindow{Opacity=0,ShowInTaskbar=false,Width=1600,Height=900};window.Show();await Wait(()=>Field<bool>(window,"libraryReady")&&Field<bool>(window,"sessionReady"));
   var search=Field<TextBox>(window,"Search");foreach(var (view,prompt) in new[]{("albums","hangi albümü arıyorsun?"),("artists","hangi sanatçıyı arıyorsun?"),("playlists","hangi listeyi arıyorsun?"),("tracks","hangi parçayı arıyorsun?"),("queue","hangi parçayı arıyorsun?")}){Set(window,"view",view);Call(window,"RefreshView");window.UpdateLayout();search.ApplyTemplate();var hint=(TextBlock)search.Template.FindName("SearchHint",search);Check(Equals(search.Tag,prompt)&&search.Text==""&&hint.IsVisible&&hint.Opacity<1,"Empty search shows a page-specific muted prompt without inserting query text: "+view);}
   Set(window,"view","tracks");Call(window,"RefreshView");window.UpdateLayout();Check(!Field<TextBlock>(window,"SectionTitle").IsVisible&&Field<TextBlock>(window,"SectionTitle").Text=="","All-tracks page removes the redundant double-click heading");var filters=Field<WrapPanel>(window,"TrackFilters");var rating=Field<StackPanel>(window,"RatingFilterTools");var help=Field<Button>(window,"FilterHelpButton");Check(filters.Children.IndexOf(rating)<filters.Children.IndexOf(help)&&rating.Children.Count==1&&rating.Children[0] is ComboBox,"Rating dropdown precedes filter help and has no extra visible label");
   Rect Bounds(FrameworkElement node,FrameworkElement ancestor)=>node.TransformToAncestor(ancestor).TransformBounds(new Rect(node.RenderSize));var content=Field<Grid>(window,"MainContent");var tracks=Field<DataGrid>(window,"Tracks");var heart=(SvgIcon)Field<DataGridTemplateColumn>(window,"TrackFavoriteColumn").Header;DependencyObject? heartParent=heart;while(heartParent!=null&&heartParent is not System.Windows.Controls.Primitives.DataGridColumnHeader)heartParent=System.Windows.Media.VisualTreeHelper.GetParent(heartParent);var heartHeader=(System.Windows.Controls.Primitives.DataGridColumnHeader)heartParent!;var heartBounds=Bounds(heart,heartHeader);Check(heart.ActualWidth>=18&&heartBounds.Left>=heartHeader.Padding.Left-.1&&heartBounds.Right<=heartHeader.ActualWidth-heartHeader.Padding.Right+.1&&Math.Abs((heartBounds.Left+heartBounds.Right)/2-heartHeader.ActualWidth/2)<.5,"The complete favorite-header heart fits its narrow column and stays centered");Check(Bounds(tracks,content).Top-Bounds(help,content).Bottom>=15.5,"Track filters retain a clear gap above the list");
   search.Text="\"Track 2\"";Call(window,"RefreshView");window.UpdateLayout();Check(tracks.Items.Count==1&&((Track)tracks.Items[0]).Title=="Track 2"&&!((TextBlock)search.Template.FindName("SearchHint",search)).IsVisible,"Typing still filters tracks and hides the prompt: count="+tracks.Items.Count+", hint="+((TextBlock)search.Template.FindName("SearchHint",search)).Visibility+", text="+search.Text);search.Text="";Call(window,"RefreshView");window.UpdateLayout();Check(tracks.Items.Count==4&&((TextBlock)search.Template.FindName("SearchHint",search)).IsVisible,"Clearing search restores the collection and prompt");var ratingCombo=Field<ComboBox>(window,"RatingFilter");ratingCombo.SelectedIndex=6;Call(window,"RefreshView");Check(tracks.Items.Count==0,"Moved rating dropdown still filters tracks by five-star ratings");ratingCombo.SelectedIndex=0;Call(window,"RefreshView");Check(tracks.Items.Count==4,"Restoring all ratings returns the full track list");
   window.Width=1120;InterfaceSettings.Current.FontScale=125;Call(window,"ApplyInterfacePreferences",false);window.UpdateLayout();await Task.Delay(60);window.UpdateLayout();var smart=Field<ComboBox>(window,"SmartView");var smartBounds=Bounds(smart,filters);var ratingBounds=Bounds(rating,filters);var helpBounds=Bounds(help,filters);Check(!smartBounds.IntersectsWith(ratingBounds)&&!ratingBounds.IntersectsWith(helpBounds)&&new[]{smartBounds,ratingBounds,helpBounds}.All(bounds=>bounds.Right<=filters.ActualWidth+.5),"Narrow-window filters wrap without overlaps or clipping at large font scale");Check(Bounds(tracks,content).Top-Bounds(help,content).Bottom>=15.5,"Wrapped filter rows still leave space above tracks");
   var audio=Field<AudioEngine>(window,"audio");double volume=audio.Volume;bool muted=audio.Muted;Call(window,"SetSignal",raw);var signal=Field<TextBlock>(window,"Signal");var box=Field<Border>(window,"SignalBox");Check(signal.Text==compact&&box.ContextMenu!=null,"Signal box owns a native right-click customization menu");MenuItem Item(string label)=>box.ContextMenu!.Items.OfType<MenuItem>().Single(item=>AutomationProperties.GetName(item)==label);Item("Çıkış aygıtı").RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(!signal.Text.Contains("Soundbar")&&signal.Text.Contains("Kaynak:")&&!Item("Çıkış aygıtı").IsChecked,"Menu toggles change the live signal text and checkmark");Item("ReplayGain").RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(signal.Text.Contains("ReplayGain")&&Item("ReplayGain").IsChecked,"Initially hidden fields can be enabled from the right-click menu");Item("ReplayGain").RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Item("Başlığı göster").RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(!signal.Text.Contains("ReplayGain")&&!Field<TextBlock>(window,"SignalHeading").IsVisible,"Signal heading and ReplayGain visibility are independently customizable");Check(!audio.DeviceStarted&&audio.Volume==volume&&audio.Muted==muted,"Changing display preferences never starts playback or changes audio volume");
   var saved=PlayerJson.Read<SignalDisplayPreferences>(Path.Combine(Paths.Data,"signal-display.json"))!;Check(saved.Hidden.Contains("device")&&saved.Hidden.Contains("gain")&&!saved.ShowHeading,"Signal display selections persist atomically outside audio settings");window.Close();window=null;window=new MainWindow{Opacity=0,ShowInTaskbar=false};window.Show();await Wait(()=>Field<bool>(window,"sessionReady"));Call(window,"SetSignal",raw);Check(!Field<TextBlock>(window,"Signal").Text.Contains("Soundbar")&&!Field<TextBlock>(window,"Signal").Text.Contains("ReplayGain")&&!Field<TextBlock>(window,"SignalHeading").IsVisible,"Signal selections survive application restart");box=Field<Border>(window,"SignalBox");box.ContextMenu!.Items.OfType<MenuItem>().Single(item=>Equals(item.Header,"Varsayılanlara dön")).RaiseEvent(new RoutedEventArgs(MenuItem.ClickEvent));Check(Field<TextBlock>(window,"Signal").Text==compact&&Field<TextBlock>(window,"SignalHeading").IsVisible,"Reset restores the compact signal defaults immediately");Check(!Field<AudioEngine>(window,"audio").DeviceStarted,"UI validation never opens a sound output device");
  }
  finally{window?.Close();File.WriteAllText(Path.Combine(directory,"collection-ui-results.json"),JsonSerializer.Serialize(checks,new JsonSerializerOptions{WriteIndented=true}));}
 }
}
